// Map only messages generated by this application, without changing backend
// error contracts or rewriting unknown details from providers and the OS.
type ErrorArea = 'sensitiveWords' | 'reverseProxyTls' | 'acp';

const sensitiveWordErrors: ReadonlyArray<[pattern: string, summary: string]> = [
  ['Cloud rule file exceeds 1 MiB', 'O arquivo de regras da nuvem excede 1 MiB.'],
  ['Rule file must contain antigravity or devin', 'O arquivo de regras deve conter uma seção antigravity ou devin.'],
  ['Rule file may contain at most 2000 entries', 'O arquivo de regras pode conter no máximo 2.000 entradas.'],
  ['Invalid rule JSON:', 'O JSON do arquivo de regras é inválido.'],
];

const tlsPrefixes: ReadonlyArray<[prefix: string, translation: string]> = [
  ['Certificate file does not exist: ', 'O arquivo de certificado não existe: '],
  ['Failed to read certificate file ', 'Não foi possível ler o arquivo de certificado '],
  ['Failed to parse certificate PEM in ', 'Não foi possível ler o certificado PEM em '],
  ['No certificates found in ', 'Nenhum certificado encontrado em '],
  ['Private key file does not exist: ', 'O arquivo de chave privada não existe: '],
  ['Failed to read private key file ', 'Não foi possível ler o arquivo de chave privada '],
  ['Failed to parse private key PEM in ', 'Não foi possível ler a chave privada PEM em '],
  ['No private key found in ', 'Nenhuma chave privada encontrada em '],
  ['Invalid TLS certificate/key configuration: ', 'Configuração inválida do certificado ou da chave TLS: '],
];

export function localizedOwnError(area: ErrorArea, error: unknown, locale: string): string {
  const original = String(error);
  if (locale !== 'pt-BR') return original;
  const message = error instanceof Error ? error.message : original;
  if (area === 'acp') {
    return message === 'Refresh available ACP models first'
      ? 'Atualize primeiro a lista de modelos ACP disponíveis.'
      : original;
  }
  if (area === 'reverseProxyTls') {
    for (const [prefix, translation] of tlsPrefixes) {
      if (message.startsWith(prefix)) return translation + message.slice(prefix.length);
    }
  }
  if (area === 'sensitiveWords') {
    const wrapped = message.startsWith('GitHub API: ') && message.includes('; Raw fallback: ');
    const fallback = wrapped ? message.slice(message.indexOf('; Raw fallback: ') + '; Raw fallback: '.length) : message;
    for (const [pattern, summary] of sensitiveWordErrors) {
      if (fallback === pattern || (pattern.endsWith(':') && fallback.startsWith(pattern))) {
        return wrapped || pattern.endsWith(':') ? `${summary} (${message})` : summary;
      }
    }
  }
  return original;
}
